const currentUserId = pluginVariables[/* Supabase Auth user */ '1fa0dd68-5069-436c-9a7d-3b54c340f1fa']['user']?.['id'];
const targetUserId = globalContext.pageParameters['id'] || currentUserId;

if (!targetUserId) return [];

const collectionType = variables['770d0a47-b9a7-4422-948e-310618e0ccbb'];
const allRatings = collections[/* Supabase UserRatingsByPage */ '5bdbd040-1492-4148-9c7f-7327eff701c5']?.data || [];

// БЕЗОПАСНО ОБЪЕДИНЯЕМ ДАННЫЕ ИЗ НЕСКОЛЬКИХ КОЛЛЕКЦИЙ
const allGames = [].concat(
    collections[/* GamesUserFavoritesByPage */ 'dd06bee7-9730-43e6-9d1c-2a9449310c78']?.data || [],
    collections[/* GamesUserLovedByPage */ 'da0c43b4-a943-45ee-af56-5559031b51b2']?.data || [],
    collections[/* GamesUserNowPlayByPage */ 'b42b2631-f453-472e-8dd7-e80d27501c48']?.data || [],
    collections[/* GamesUserWillPlayByPage */ '09509266-2104-41e4-a757-f43facfd5f8a']?.data || [],
    collections[/* GamesUserDoneByPage */ '15162c69-9cb9-4cf9-94bc-b8c33bb75fcc']?.data || []
);

let userCollectionItems = [];

switch (collectionType) {
    case "избранное":
        userCollectionItems = collections[/* Supabase AllFavorites */ '72a6cf84-8907-4238-a666-a55012fafdc5']?.data?.filter(item => item.user_id === targetUserId) || [];
        break;
    case "любимые игры":
        userCollectionItems = collections[/* SupabaseAllLoved */ '368d9053-911f-44d3-8064-ebdfc605a5dc']?.data?.filter(item => item.user_id === targetUserId) || [];
        break;
    case "буду играть":
        userCollectionItems = collections[/* Supabase AllWillPlay */ '18c5c122-e957-4b31-a6e9-9f98c9051ae5']?.data?.filter(item => item.user_id === targetUserId) || [];
        break;
    case "играю":
        userCollectionItems = collections[/* SupabaseAllNowPlay */ '0961c504-2373-4fba-a33c-3fd19cb16ade']?.data?.filter(item => item.user_id === targetUserId) || [];
        break;
    case "пройдено":
        userCollectionItems = collections[/* SupabaseAllDone */ '52f820d2-10bd-41a6-b11f-48366beabaed']?.data?.filter(item => item.user_id === targetUserId) || [];
        break;
    default:
        return [];
}

// Проверяем что userCollectionItems - массив
if (!Array.isArray(userCollectionItems)) {
    console.error('userCollectionItems is not an array:', userCollectionItems);
    return [];
}

// Убираем дубликаты игр
const uniqueGames = allGames.filter((game, index, self) =>
    index === self.findIndex(g => g.id === game.id)
);

// Объединяем с данными игр и рейтингами
return userCollectionItems.map(item => {
    const game = uniqueGames.find(g => g.id === item.game_id);
    if (!game) return null;

    // Находим рейтинг пользователя для этой игры
    const userRating = allRatings.find(r => r.user_id === targetUserId && r.game_id === item.game_id);

    return {
        ...game,
        collectionData: item,
        userRating: userRating?.ratingvalue || null,
        // ДОБАВЛЯЕМ ДАТУ СОЗДАНИЯ ИЗ КОЛЛЕКЦИЙ
        created_at: item.created_at || item.inserted_at || null
    };
}).filter(Boolean);

