const EXP = collections[/* User EXP */ 'f37fb37d-a3c6-42ca-bff5-f16e5a5cae9f']?.['data']?.[0]?.['EXP'] || 0;

const expTable = [0, 15, 40, 80, 150, 250, 400, 600, 850, 1150];

let level = 1;
for (let i = expTable.length - 1; i >= 0; i--) {
    if (EXP >= expTable[i]) {
        level = i + 1;
        break;
    }
}

const currentExp = expTable[level - 1] || 0;
const nextExp = expTable[level] || expTable[expTable.length - 1] + 200;

const progress = ((EXP - currentExp) / (nextExp - currentExp)) * 100;

return Math.min(progress, 100);

